def nk(value: str) -> str:
    value = value.lower().strip()
    value = re.sub(r"[^a-z0-9]+", "-", value)
    return value.strip("-") or "unknown"


def main() -> None:
    OUTDIR.mkdir(parents=True, exist_ok=True)
    total = 0
    for slug, payload in PAYLOADS.items():
        city = payload['records'][0]['city'] if payload.get('records') else slug
        outpath = OUTDIR / f"{nk(city)}.json"
        if outpath.exists():
            print(f"SKIP  {city}: {outpath.name} already exists")
            continue
        outpath.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        count = len(payload.get('records', []))
        total += count
        print(f"WRITE {city}: {count} records -> {outpath.name}")
    print(f"Total written records: {total}")


if __name__ == '__main__':
    main()
